#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

banner "Mobile dev environment — Xcode + Android Studio"

# ── Stage 1: pre-flight ───────────────────────────────────────────────────
stage "Pre-flight check"
say "This machine needs full Xcode and an Android SDK to build, run, and"
say "profile the Tin Ha Tai Ping game on iOS and Android."
free_kb=$(df -k / | awk 'NR==2 {print $4}')
free_gb=$((free_kb / 1048576))
note "Free disk space: ${free_gb} GB (Xcode + Android Studio want ~60 GB)"
(( free_gb >= 60 )) || warn "Low on disk — consider freeing space first."
macos_ver=$(sw_vers -productVersion 2>/dev/null || echo "unknown")
note "macOS: ${macos_ver} (current Xcode needs 14.5+)"
note "Arch: $(uname -m)"
pause "Checks done — press Enter to start the Xcode install."

# ── Stage 2: Xcode install ────────────────────────────────────────────────
stage "Install Xcode from the Mac App Store"
if [[ -d /Applications/Xcode.app ]]; then
  note "Xcode already present at /Applications/Xcode.app — skipping install."
else
  say "Xcode is a large download (~12 GB) and can take 30–60 minutes."
  open_url "macappstore://apps.apple.com/app/xcode/id497799835"
  step "In the App Store, click Get/Install for Xcode."
  step "Wait for the download AND installation to fully finish"
  step "(the App Store 'Install' progress must complete on its own)."
  note "You can pause/resume the download from the App Store account view."
  pause "Xcode fully installed? Press Enter to continue."
  if [[ ! -d /Applications/Xcode.app ]]; then
    warn "Couldn't find /Applications/Xcode.app"
    pause "Install it (or move it into /Applications), then press Enter."
    [[ -d /Applications/Xcode.app ]] || { warn "Xcode still missing — exiting."; exit 1; }
  fi
fi

# ── Stage 3: activate + verify Xcode ──────────────────────────────────────
stage "Activate the Xcode toolchain"
say "Xcode ships inactive until the developer directory is switched and the"
say "license accepted. sudo will ask for your Mac password."
step "Enter your Mac password when prompted."
sudo xcode-select --switch /Applications/Xcode.app/Contents/Developer
sudo xcodebuild -license accept
say "Installing required components (simulators, headers) — a few minutes…"
xcodebuild -runFirstLaunch || true
say "Verification:"
xcodebuild -version
note "Available iOS simulators:"
xcrun simctl list devices available | sed -n '1,12p'
pause "Xcode verified — press Enter to move on to Android Studio."

# ── Stage 4: Android Studio install ───────────────────────────────────────
stage "Install Android Studio"
if [[ -d /Applications/Android\ Studio.app ]]; then
  note "Android Studio already present — skipping install."
else
  open_url "https://developer.android.com/studio"
  step "Download the .dmg (choose the Apple Silicon / ARM chip option)."
  step "Open the .dmg and drag Android Studio into Applications."
  step "Launch Android Studio from Applications."
  step "In its setup wizard choose Standard and let it finish —"
  step "this installs the Android SDK, platform-tools, and emulator."
  pause "Setup wizard finished? Press Enter to continue."
fi

# ── Stage 5: shell profile env vars ───────────────────────────────────────
stage "Add the Android SDK to your shell profile"
SDK_DIR="$HOME/Library/Android/sdk"
if [[ ! -d "$SDK_DIR" ]]; then
  warn "Default SDK path not found: $SDK_DIR"
  ask SDK_DIR "Enter your Android SDK path:"
fi
export ANDROID_HOME="$SDK_DIR"
export PATH="$PATH:$ANDROID_HOME/platform-tools"
PROFILE="$HOME/.zshrc"
say "Will write to: $PROFILE"
if grep -q '^export ANDROID_HOME=' "$PROFILE" 2>/dev/null; then
  note "ANDROID_HOME already exported in $PROFILE — leaving it alone."
else
  if confirm "Append ANDROID_HOME + platform-tools PATH to $PROFILE?"; then
    printf '\n# Android SDK (added by setup wizard)\nexport ANDROID_HOME="%s"\nexport PATH="$PATH:$ANDROID_HOME/platform-tools"\n' "$SDK_DIR" >> "$PROFILE"
    say "✓ appended. Open a NEW terminal (or run: source ~/.zshrc) to pick it up."
  else
    note "Skipped — add it yourself if builds need it."
  fi
fi

# ── Stage 6: Pixel 6a emulator (floor device) ─────────────────────────────
stage "Create a Pixel 6a emulator (the perf floor device)"
EMU="$ANDROID_HOME/emulator/emulator"
SDKMGR="$ANDROID_HOME/cmdline-tools/latest/bin/sdkmanager"
AVDMGR="$ANDROID_HOME/cmdline-tools/latest/bin/avdmanager"
if [[ -x "$EMU" ]] && "$EMU" -list-avds 2>/dev/null | grep -q .; then
  note "An emulator already exists:"
  "$EMU" -list-avds
  pause "Press Enter to continue."
elif [[ -x "$SDKMGR" && -x "$AVDMGR" ]]; then
  say "Installing a Pixel 6a system image (a few GB download)…"
  yes | "$SDKMGR" --licenses >/dev/null 2>&1 || true
  "$SDKMGR" "system-images;android-35;google_apis;arm64-v8a" >/dev/null 2>&1 || true
  if "$AVDMGR" create avd -n pixel6a -k "system-images;android-35;google_apis;arm64-v8a" -d pixel --force 2>/dev/null; then
    note "✓ created AVD 'pixel6a'"
  else
    warn "CLI AVD creation failed — use the UI instead."
  fi
fi
if [[ -x "$EMU" ]] && ! "$EMU" -list-avds 2>/dev/null | grep -q .; then
  warn "No emulator AVD found yet."
  step "Open Android Studio → Device Manager → Create Virtual Device."
  step "Pick Pixel 6a, system image API 34+ (Google APIs, ARM64), finish."
  pause "AVD created? Press Enter to continue."
fi

# ── Stage 7: final verification ───────────────────────────────────────────
stage "Final verification"
say "iOS toolchain:"
if command -v xcodebuild >/dev/null; then
  xcodebuild -version | head -1
  ios_sims=$(xcrun simctl list devices available 2>/dev/null | grep -c "iPhone" || true)
  note "  ${ios_sims} iPhone simulator(s) available"
else
  warn "  xcodebuild not found — Xcode stage incomplete"
fi
say "Android toolchain:"
if command -v adb >/dev/null; then
  adb version | head -1
else
  warn "  adb not on PATH — check stage 5 profile export"
fi
if [[ -x "$EMU" ]]; then
  note "  emulators: $("$EMU" -list-avds 2>/dev/null | tr '\n' ' ' || echo none)"
else
  warn "  emulator binary not found"
fi
say "Node:"
node --version
note ""
note "All green? Tell your fs-pm agent: 「environment ready」"
note "— it will then unlock renderer tickets 04–07."

finish
}

run_wizard "$@"; exit
